--
-- Name: allocate_project_node_event_sequence(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.allocate_project_node_event_sequence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE next_value bigint;
BEGIN
  IF NEW.sequence_number IS NULL OR NEW.sequence_number = 0 THEN
    INSERT INTO public.project_event_counters(project_id, next_sequence, updated_at)
    VALUES (NEW.project_id, 1, now())
    ON CONFLICT (project_id) DO UPDATE
      SET next_sequence = public.project_event_counters.next_sequence + 1,
          updated_at = now()
    RETURNING next_sequence INTO next_value;
    NEW.sequence_number := next_value;
  ELSE
    IF EXISTS (
      SELECT 1 FROM public.project_event_counters
      WHERE project_id = NEW.project_id AND next_sequence >= NEW.sequence_number
    ) THEN
      RETURN NEW;
    END IF;
    INSERT INTO public.project_event_counters(project_id, next_sequence, updated_at)
    VALUES (NEW.project_id, NEW.sequence_number, now())
    ON CONFLICT (project_id) DO UPDATE
      SET next_sequence = greatest(public.project_event_counters.next_sequence, excluded.next_sequence),
          updated_at = now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.allocate_project_node_event_sequence() OWNER TO postgres;

--
-- Name: dismiss_orphan_notifications(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dismiss_orphan_notifications() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  ref_key text;
  now_ts timestamptz := now();
BEGIN
  ref_key := TG_ARGV[0];
  UPDATE public.user_notifications
  SET dismissed_at = now_ts,
      read_at = COALESCE(read_at, now_ts),
      seen_at = COALESCE(seen_at, now_ts),
      updated_at = now_ts
  WHERE dismissed_at IS NULL
    AND entity_refs ->> ref_key = OLD.id::text;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.dismiss_orphan_notifications() OWNER TO postgres;

--
-- Name: enforce_profile_username_rules(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_profile_username_rules() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
        begin
            if new.username is null then
                return new;
            end if;

            new.username := lower(trim(new.username));

            if new.username !~ '^[a-z0-9_]{3,20}$' then
                raise exception using errcode = '23514', message = 'Invalid username format';
            end if;

            if exists (
                select 1 from public.reserved_usernames where username = new.username
            ) then
                raise exception using errcode = '23514', message = 'Username is reserved';
            end if;

            return new;
        end;
        $_$;


ALTER FUNCTION public.enforce_profile_username_rules() OWNER TO postgres;

--
-- Name: record_file_content_contribution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_file_content_contribution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE project_uuid uuid;
BEGIN
  IF current_setting('app.maintenance_operation', true) IN ('hash_backfill', 'version_repair') THEN
    RETURN NEW;
  END IF;
  IF auth.uid() IS NOT NULL AND (NEW.uploaded_by IS DISTINCT FROM auth.uid() OR NEW.attribution <> '{}'::jsonb) THEN
    RAISE EXCEPTION 'File authorship must match the authenticated actor';
  END IF;
  IF TG_OP = 'UPDATE'
    AND NEW.s3_key IS NOT DISTINCT FROM OLD.s3_key
    AND NEW.size IS NOT DISTINCT FROM OLD.size
    AND NEW.mime_type IS NOT DISTINCT FROM OLD.mime_type THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.content_hash IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.file_versions previous WHERE previous.node_id=NEW.node_id
      AND previous.version=NEW.version-1 AND previous.content_hash=NEW.content_hash
  ) THEN RETURN NEW; END IF;
  SELECT project_id INTO project_uuid FROM public.project_nodes WHERE id = NEW.node_id;
  INSERT INTO public.project_node_events(project_id,node_id,actor_id,type,sequence_number,metadata)
  VALUES (project_uuid,NEW.node_id,NEW.uploaded_by,'file_content_contributed',0,
    jsonb_build_object('version',NEW.version,'hash',NEW.content_hash,'source',COALESCE(NEW.attribution->>'source','edge'),'attribution',NEW.attribution));
  IF NEW.uploaded_by IS NOT NULL THEN
    UPDATE public.profile_collaboration_summaries SET stale=true,updated_at=now() WHERE profile_id=NEW.uploaded_by;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.record_file_content_contribution() OWNER TO postgres;

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.rls_auto_enable() OWNER TO postgres;

