--
-- Name: sync_profile_to_auth_user_metadata(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_profile_to_auth_user_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.avatar_url IS NOT NULL OR NEW.full_name IS NOT NULL OR NEW.username IS NOT NULL THEN
    UPDATE auth.users
    SET raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'avatar_url', NEW.avatar_url,
      'full_name', NEW.full_name,
      'username', NEW.username
    ))
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_profile_to_auth_user_metadata() OWNER TO postgres;

--
-- Name: sync_project_open_roles_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_project_open_roles_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  p_id uuid;
BEGIN
  p_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.project_id ELSE NEW.project_id END;
  UPDATE public.projects
  SET open_roles_count = (
    SELECT count(*)
    FROM public.project_open_roles
    WHERE project_id = p_id AND filled < count
  )
  WHERE id = p_id;
  RETURN NULL;
END;
$$;


