--
-- Name: role_applications chat_card_changed_application; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER chat_card_changed_application AFTER UPDATE OF status ON public.role_applications FOR EACH ROW WHEN ((old.status IS DISTINCT FROM new.status)) EXECUTE FUNCTION app_private.chat_card_changed('application');


--
-- Name: project_invitations chat_card_changed_invite; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER chat_card_changed_invite AFTER UPDATE OF status ON public.project_invitations FOR EACH ROW WHEN ((old.status IS DISTINCT FROM new.status)) EXECUTE FUNCTION app_private.chat_card_changed('invite');


--
-- Name: tasks chat_card_changed_task; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER chat_card_changed_task AFTER UPDATE OF status, assignee_id, title, priority, due_date ON public.tasks FOR EACH ROW WHEN (((old.status IS DISTINCT FROM new.status) OR (old.assignee_id IS DISTINCT FROM new.assignee_id) OR (old.title IS DISTINCT FROM new.title) OR (old.priority IS DISTINCT FROM new.priority) OR (old.due_date IS DISTINCT FROM new.due_date))) EXECUTE FUNCTION app_private.chat_card_changed('task');


