--
-- Name: account_deletions account_deletions_select_own; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY account_deletions_select_own ON public.account_deletions FOR SELECT USING ((user_id = ( SELECT auth.uid() AS uid)));


--
-- Name: app_migration_journal; Type: ROW SECURITY; Schema: public; Owner: postgres
