--
-- Name: application_events; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.application_events ENABLE ROW LEVEL SECURITY;

--
-- Name: application_events application_events_select_actor_or_project_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY application_events_select_actor_or_project_admin ON public.application_events FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.role_applications application
  WHERE ((application.id = application_events.application_id) AND ((application.applicant_id = ( SELECT auth.uid() AS uid)) OR app_private.nb_project_can_admin(application.project_id))))));


