--
-- Name: comment_mentions; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE public.comment_mentions ENABLE ROW LEVEL SECURITY;

--
-- Name: comment_mentions comment_mentions_insert_project_member; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY comment_mentions_insert_project_member ON public.comment_mentions FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM public.task_comments tc
  WHERE ((tc.id = comment_mentions.comment_id) AND (tc.user_id = ( SELECT auth.uid() AS uid))))));


--
-- Name: comment_mentions comment_mentions_select_author_or_project_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY comment_mentions_select_author_or_project_admin ON public.comment_mentions FOR SELECT USING (((mentioned_user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM ((public.task_comments tc
     JOIN public.tasks t ON ((tc.task_id = t.id)))
     JOIN public.projects p ON ((t.project_id = p.id)))
  WHERE ((tc.id = comment_mentions.comment_id) AND ((p.owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
           FROM public.project_members m
          WHERE ((m.project_id = p.id) AND (m.user_id = ( SELECT auth.uid() AS uid)))))))))));


