-- Name: file_versions file_versions_insert_project_member; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY file_versions_insert_project_member ON public.file_versions FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM (public.project_nodes pn
     JOIN public.projects p ON ((pn.project_id = p.id)))
  WHERE ((pn.id = file_versions.node_id) AND ((p.owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
           FROM public.project_members m
          WHERE ((m.project_id = p.id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (m.role <> 'viewer'::text)))))))));


