   FROM (public.project_updates u
     JOIN public.projects p ON ((p.id = u.project_id)))
  WHERE ((u.id = project_update_comments.update_id) AND (u.project_id = project_update_comments.project_id) AND (u.deleted_at IS NULL) AND (p.deleted_at IS NULL) AND ((p.owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
           FROM public.project_members m
          WHERE ((m.project_id = p.id) AND (m.user_id = ( SELECT auth.uid() AS uid))))) OR ((p.visibility = 'public'::text) AND (u.visibility = 'public'::text) AND (u.reply_policy = 'logged_in'::text) AND ((COALESCE(p.public_tab_visibility, '{}'::jsonb) ->> 'updates'::text) IS DISTINCT FROM 'false'::text))))))));


