          WHERE ((m.project_id = p.id) AND (m.user_id = ( SELECT auth.uid() AS uid))))) OR ((p.visibility = 'public'::text) AND (u.visibility = 'public'::text) AND ((COALESCE(p.public_tab_visibility, '{}'::jsonb) ->> 'updates'::text) IS DISTINCT FROM 'false'::text)))))));


